import{prepare,ready}from'./browser.js';
export const records=[{id:1,name:'Carteira cliente A',cnpj:'00000000000100',address:'Rua A, Natal',city:'Natal',neighborhood:'Tirol',lat:-5.8,lon:-35.2,locationVerification:'manual_reviewed',active:true,priority:2,importFields:[]},{id:2,name:'Carteira cliente B',cnpj:'00000000000272',address:'Rua B, Natal',city:'Natal',lat:-5.81,lon:-35.21,locationVerification:'manual_reviewed',active:true,priority:2,importFields:[]}];
export async function setup(page){await prepare(page,{records,lockAuthFixture:true});await page.addInitScript(({records})=>{const owner='00000000-0000-4000-8000-000000000001',portfolio='00000000-0000-4000-8000-000000000000';if(!localStorage.getItem('__version_clients'))localStorage.setItem('__version_clients',JSON.stringify(records.map(c=>({local_id:String(c.id),data:c,revision:1,deleted_at:null,portfolio_id:portfolio}))));const base=window.supabase.createClient;window.supabase.createClient=(...args)=>{const api=base(...args),from=api.from,rpc=api.rpc,clients=()=>JSON.parse(localStorage.getItem('__version_clients')),versions=()=>JSON.parse(localStorage.getItem('__version_versions')||'[]');api.from=table=>{if(!['clients','rotamapa_portfolio_versions'].includes(table))return from(table);let filters=[],start=0,end=499,single=false;const q={select:()=>q,eq:(k,v)=>{if(k!=='user_id')filters.push([k,v]);return q;},order:()=>q,range:(a,b)=>{start=a;end=b;return q;},limit:()=>q,single:()=>{single=true;return q;},then:(resolve,reject)=>{const all=(table==='clients'?clients():versions()).filter(row=>filters.every(([k,v])=>row[k]===v)).slice(start,end+1);return Promise.resolve({data:single?all[0]||null:all,error:null}).then(resolve,reject);}};return q;};api.rpc=async(name,p)=>{if(name!=='rotamapa_replace_portfolio')return rpc(name,p);if(window.__versionFailure)return{error:{code:'40001',message:'A carteira mudou em outro aparelho.'}};const all=clients(),expected=all.filter(r=>!r.deleted_at).map(r=>({id:r.local_id,revision:r.revision}));if(JSON.stringify(p.p_expected)!==JSON.stringify(expected))return{error:{code:'40001',message:'A carteira mudou em outro aparelho.'}};const before=all.map(r=>r.data),next=p.p_clients.map(data=>{const old=all.find(r=>r.local_id===String(data.id));return{local_id:String(data.id),data,revision:(old?.revision||0)+1,deleted_at:null,portfolio_id:portfolio};});localStorage.setItem('__version_versions',JSON.stringify([...versions(),{user_id:owner,portfolio_id:portfolio,id:p.p_operation,label:p.p_label,source:p.p_source,clients:before,created_at:new Date().toISOString()}]));localStorage.setItem('__version_clients',JSON.stringify(next));return{data:{id:p.p_operation,clients:next}};};return api;};},{records});await ready(page);await page.waitForFunction(()=>window.RotaMapaPortfolioVersions);}
export const spreadsheet=()=>({name:'carteira-novembro.csv',mimeType:'text/csv',buffer:Buffer.from('Razão social;CNPJ;Rua;Cidade\nCarteira cliente A atualizado;00000000000100;Nova coluna recebida;Natal\nCarteira cliente C;00000000000353;Rua C;Natal\n')});
